class Parrot(Bird):
    # override sound() to return "Hello!"
    pass

class Crow(Bird):
    def sound(self):
        return "Caw!"

for b in [Bird(), Parrot(), Crow()]:
    print(b.sound())</textarea></div></div><div class="lx-outbox"><div class="lx-out-h"><svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m4 17 6-6-6-6"/><path d="M12 19h8"/></svg> Output <em>Ctrl + Enter to run</em></div><pre class="lx-out-pre"><span class="lx-out-empty">Press Run to see what your code prints…</span></pre></div><div class="lx-verdict" hidden></div><div class="lx-play-foot"><button type="button" class="lx-hintbtn"><svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/></svg> <span>Need a hint?</span></button><button type="button" class="lx-solbtn"><svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg> Show solution</button></div><p class="lx-hint" hidden><strong>Hint:</strong> Define def sound(self): inside Parrot and return the string.</p><textarea class="lx-sol" hidden>class Bird:
