        return "Caw!"

for b in [Bird(), Parrot(), Crow()]:
    print(b.___())</textarea></div></div><div class="lx-outbox"><div class="lx-out-h"><svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m4 17 6-6-6-6"/><path d="M12 19h8"/></svg> Output <em>Ctrl + Enter to run</em></div><pre class="lx-out-pre"><span class="lx-out-empty">Press Run to see what your code prints…</span></pre></div><div class="lx-verdict" hidden></div><div class="lx-play-foot"><button type="button" class="lx-hintbtn"><svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/></svg> <span>Need a hint?</span></button></div><p class="lx-hint" hidden><strong>Hint:</strong> Use the same method name in the child. Python picks the child version first.</p></div></div></div></div></section></div><div class="lx-pager"><button type="button" class="lx-btn ghost lx-pg-prev" hidden><svg class="flip" xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg> Previous</button><span class="lx-pg-hint"></span><button type="button" class="lx-pg-skip">Skip for now</button><button type="button" class="lx-btn lx-pg-next" disabled><span class="lbl">Next practice</span> <svg xmlns="http://www.w3.org/2000/svg" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></div><div class="lx-wrapup" data-total="8"><div class="ic"><svg x